class BatteryAgent:
    def __init__(self):
        self.eta = 0.9 ** 0.5
        self.cap = 6000.0
        self.power_max = 1500.0
        # Pesos calibrats sobre el baseline del Mode Difícil (0,7·ΔCO2 + 0,3·ΔCost)
        self.w_co2 = 3.82
        self.w_price = 1.0
        self.v_term_quantile = 0.60
        self.margin_kw = 30.0
        self.horizon = 24
        self._mats_cache = {}
        self._tables = None
        self._cloud = 1.0
        self.cloud_alpha = 0.5
        self.w_analog_co2 = 0.5
        self.w_analog_load = 1.0
        self._load_hist = []
        self._load_tables()

    # ---------------------------------------------------------------- taules
    def _load_tables(self):
        path = Path(__file__).parent / "hard_tables.pkl"
        try:
            with open(path, "rb") as f:
                self._tables = pickle.load(f)
        except Exception:
            self._tables = _EMBEDDED_TABLES

    def _tab(self, name, month, hour):
        if self._tables is not None:
            return float(self._tables[name][month, hour])
        if name == "price_prof":
            return 0.14
        if name == "co2_prof":
            return 0.085
        if name == "pv_prof":
            return 0.0
        if name == "load_prof":
            return 1120.0
        return 0.0

    @staticmethod
    def _clip(x, lo, hi):
        return float(max(lo, min(hi, x)))

    # ------------------------------------------------------------ matrius LP
    def _get_matrices(self, horizon, cap, power):
        key = (horizon, cap, power)
        if key in self._mats_cache:
            return self._mats_cache[key]

        # Variables: [c_0..c_{H-1}, d_0..d_{H-1}, soc_0..soc_{H-1}, g_0..g_{H-1}]
        n = 4 * horizon
        a_eq = lil_matrix((horizon, n))
        a_ub = lil_matrix((horizon, n))
        for t in range(horizon):
            a_eq[t, 2 * horizon + t] = 1.0                 # soc[t]
            if t > 0:
                a_eq[t, 2 * horizon + t - 1] = -1.0        # -soc[t-1]
            a_eq[t, t] = -self.eta                         # -eta*c
            a_eq[t, horizon + t] = 1.0 / self.eta           # +d/eta

            # g >= net + c - d  ->  -g + c - d <= -net
            a_ub[t, 3 * horizon + t] = -1.0
            a_ub[t, t] = 1.0
            a_ub[t, horizon + t] = -1.0

        bounds = (
            [(0.0, power)] * horizon
            + [(0.0, power)] * horizon
            + [(0.0, cap)] * horizon
            + [(0.0, None)] * horizon
        )
        self._mats_cache[key] = (csc_matrix(a_eq), csc_matrix(a_ub), bounds)
        return self._mats_cache[key]

    @staticmethod
    def _cal(obs):
        """Calendar (mes, hora, dia de la setmana) robust a timestamp string/Timestamp."""
        ts = obs.get("timestamp")
        try:
            month = int(ts.month) - 1
        except Exception:
            month = int(obs.get("month", 1)) - 1
        month = max(0, min(11, month))
        hour = int(obs.get("hour", 0)) % 24
        dow = int(obs.get("day_of_week", 0)) % 7
        return month, hour, dow

    @staticmethod
    def _doy(obs):
        ts = obs.get("timestamp")
        try:
            return int(ts.dayofyear)
        except Exception:
            try:
                return int(datetime.fromisoformat(str(ts)).timetuple().tm_yday)
            except Exception:
                return None

    def _analog_co2(self, obs, base_c, hour, L, co2_a):
        """Ratios de CO2 per analogia de dies (k-NN sobre corbes diàries normalitzades)."""
        if self._tables is None or "ad_co2" not in self._tables or L == 0:
            return None
        doy = self._doy(obs)
        dow = int(obs.get("day_of_week", 0)) % 7
        if doy is None:
            return None
        ad_co2 = self._tables["ad_co2"]
        ad_doy = self._tables["ad_doy"]
        ad_dow = self._tables["ad_dow"]
        cyc = np.abs(ad_doy - doy)
        cyc = np.minimum(cyc, 365 - cyc)
        mask = (cyc <= 60) & ((ad_dow < 5) == (dow < 5))
        if not np.any(mask):
            return None
        lfit = min(L, 24 - hour)
        if lfit < 2:
            return None
        obs_r = np.array([co2_a[k] / max(base_c[(hour + k) % 24], 1e-9) for k in range(lfit)])
        idx = np.where(mask)[0]
        d = np.mean(np.abs(ad_co2[idx, hour: hour + lfit] - obs_r[None, :]), axis=1)
        idx = idx[np.argsort(d)[:8]]
        ratios = np.full(24, np.nan)
        for h in range(hour + lfit, 24):
            ratios[h] = float(np.mean(ad_co2[idx, h]))
        return ratios

    def _update_load_hist(self, obs, month, hour, dow):
        """Guarda el ratio de càrrega de l'última hora mesurada (memòria d'estat)."""
        try:
            val = float(obs.get("noves_dades_5min", {}).get("ultim_consum_kw", float("nan")))
        except (TypeError, ValueError):
            return
        if not np.isfinite(val) or val <= 0:
            return
        prev_hour = (hour - 1) % 24
        prev_dow = dow if hour > 0 else (dow - 1) % 7
        base = self._tab("load_prof", month, prev_hour)
        if self._tables is not None:
            base *= float(self._tables["load_dow"][prev_dow])
        if base <= 1.0:
            return
        ratio = val / base
        doy = self._doy(obs)
        entry_doy = doy - 1 if (doy is not None and hour == 0) else doy
        if self._load_hist:
            ldy, lh, _ = self._load_hist[-1]
            cont = False
            if entry_doy is not None and ldy is not None:
                if entry_doy == ldy and prev_hour == (lh + 1) % 24:
                    cont = True
                elif entry_doy == ldy + 1 and lh == 23 and prev_hour == 0:
                    cont = True
            elif entry_doy is None and ldy is None and prev_hour == (lh + 1) % 24:
                cont = True
            if not cont:
                self._load_hist = []
        self._load_hist.append((entry_doy, prev_hour, ratio))
        self._load_hist = self._load_hist[-3:]

    def _analog_load(self, obs, hour, dow):
        """Ratios de càrrega per analogia de dies a partir de les últimes hores conegudes."""
        if self._tables is None or "ad_load" not in self._tables or not self._load_hist:
            return None
        doy = self._doy(obs)
        if doy is None:
            return None
        ad = self._tables["ad_load"]
        ad_doy = self._tables["ad_doy"]
        ad_dow = self._tables["ad_dow"]
        cyc = np.abs(ad_doy - doy)
        cyc = np.minimum(cyc, 365 - cyc)
        mask = (cyc <= 60) & ((ad_dow < 5) == (dow < 5))
        idx = np.where(mask)[0]
        if len(idx) == 0:
            return None
        dist = np.zeros(len(idx))
        for (_, h, r) in self._load_hist:
            dist += np.abs(ad[idx, h] - r)
        idx = idx[np.argsort(dist)[:8]]
        ratios = np.full(24, np.nan)
        for h in range(hour, 24):
            ratios[h] = float(np.mean(ad[idx, h]))
        return ratios


    # ------------------------------------------------------------- previsions
    def _forecast(self, obs, horizon):
        month, hour, dow = self._cal(obs)

        try:
            prices_a = np.asarray(obs["preus_properes_24h"], dtype=float)
            co2_a = np.asarray(obs["co2_properes_24h"], dtype=float)
        except (KeyError, TypeError, ValueError):
            prices_a = np.array([])
            co2_a = np.array([])
        prices_a = np.nan_to_num(prices_a, nan=0.15, posinf=0.5, neginf=0.0)
        co2_a = np.nan_to_num(co2_a, nan=0.10, posinf=0.3, neginf=0.0)
        L = int(min(len(prices_a), len(co2_a), 3))

        load_dow = self._tables["load_dow"] if self._tables is not None else np.ones(7)
        price_dow = self._tables["price_dow"] if self._tables is not None else np.ones(7)
        co2_dow = self._tables["co2_dow"] if self._tables is not None else np.ones(7)

        H = horizon
        price_f = np.zeros(H)
        co2_f = np.zeros(H)
        load_f = np.zeros(H)
        pv_f = np.zeros(H)

        base_p = np.array([self._tab("price_prof", month, h) for h in range(24)]) * price_dow[dow]
        base_c = np.array([self._tab("co2_prof", month, h) for h in range(24)]) * co2_dow[dow]

        r_p = 1.0
        r_c = 1.0
        if L > 0:
            r_p = np.median(prices_a[:L] / np.maximum(base_p[(hour + np.arange(L)) % 24], 1e-6))
            r_c = np.median(co2_a[:L] / np.maximum(base_c[(hour + np.arange(L)) % 24], 1e-9))
            r_p = self._clip(r_p, 0.55, 1.8)
            r_c = self._clip(r_c, 0.55, 1.8)

        obs_load = float(obs.get("noves_dades_5min", {}).get("ultim_consum_kw", 1120.0))
        obs_pv = float(obs.get("noves_dades_5min", {}).get("ultima_solar_kw", 0.0))
        obs_irr = float(obs.get("noves_dades_5min", {}).get("irradiancia_wm2", 0.0))

        prev_hour = (hour - 1) % 24
        exp_load = self._tab("load_prof", month, prev_hour) * load_dow[dow]
        r_load = self._clip(obs_load / max(exp_load, 1.0), 0.75, 1.30)
        self._update_load_hist(obs, month, hour, dow)
        analog_load = self._analog_load(obs, hour, dow)

        exp_pv = self._tab("pv_prof", month, prev_hour)
        exp_irr = self._tab("irr_prof", month, prev_hour)

        # Índex de nuvolositat persistent: si l'última hora era de nit no tenim
        # mesura directa, així que mantenim l'últim índex diürn conegut.
        if exp_pv > 30.0 and obs_pv > 0.0:
            r_shape = obs_pv / exp_pv
            if exp_irr > 50.0 and obs_irr > 0.0:
                r_irr = obs_irr / exp_irr
                r_obs = 0.5 * r_shape + 0.5 * r_irr
            else:
                r_obs = r_shape
            r_obs = self._clip(r_obs, 0.0, 1.80)
            self._cloud = (1.0 - self.cloud_alpha) * self._cloud + self.cloud_alpha * r_obs
        # Si és de nit (o no hi ha mesura), mantenim self._cloud
        r_pv = self._clip(self._cloud, 0.0, 1.80)

        analog = self._analog_co2(obs, base_c, hour, L, co2_a)

        for k in range(H):
            h = (hour + k) % 24
            d = (dow + (hour + k) // 24) % 7
            price_f[k] = base_p[h] * r_p if k >= L else float(prices_a[k])
            if k < L:
                co2_f[k] = float(co2_a[k])
            elif analog is not None and hour + k < 24 and not np.isnan(analog[hour + k]):
                w_a = self.w_analog_co2
                co2_f[k] = base_c[h] * ((1.0 - w_a) * r_c + w_a * analog[hour + k])
            else:
                co2_f[k] = base_c[h] * r_c
            load_base = self._tab("load_prof", month, h) * load_dow[d]
            if analog_load is not None and hour + k < 24 and not np.isnan(analog_load[hour + k]):
                wl = self.w_analog_load
                load_f[k] = load_base * ((1.0 - wl) * r_load + wl * analog_load[hour + k])
            else:
                load_f[k] = load_base * r_load
            pv_f[k] = self._tab("pv_prof", month, h) * r_pv

        return price_f, co2_f, load_f, pv_f


    # ------------------------------------------------------------------ act
    def act(self, obs: dict) -> float:
        try:
            cap = float(obs.get("cap_max_kwh", self.cap))
            power = float(obs.get("power_max_kw", self.power_max))
        except (TypeError, ValueError):
            cap, power = self.cap, self.power_max
        if not np.isfinite(cap) or cap <= 0:
            cap = self.cap
        if not np.isfinite(power) or power <= 0:
            power = self.power_max

        soc = float(obs.get("soc_kwh", 0.5 * cap))
        soc = max(0.0, min(cap, soc))

        H = self.horizon
        price_f, co2_f, load_f, pv_f = self._forecast(obs, H)
        net_f = load_f - pv_f
        w = self.w_co2 * co2_f + self.w_price * price_f

        ts = obs.get("timestamp")
        month, hour, dow = self._cal(obs)
        future = []
        for k in range(H, H + 24):
            h = (hour + k) % 24
            future.append(self.w_co2 * self._tab("co2_prof", month, h)
                          + self.w_price * self._tab("price_prof", month, h))
        v_term = float(np.quantile(future, self.v_term_quantile)) * self.eta

        try:
            a_eq, a_ub, bounds = self._get_matrices(H, cap, power)
            b_eq = np.zeros(H)
            b_eq[0] = soc
            b_ub = -net_f

            c_obj = np.zeros(4 * H)
            c_obj[0:H] = 1e-6
            c_obj[H:2 * H] = 1e-6
            c_obj[3 * H:] = w
            c_obj[2 * H + H - 1] = -v_term

            res = linprog(c_obj, A_eq=a_eq, b_eq=b_eq, A_ub=a_ub, b_ub=b_ub,
                          bounds=bounds, method="highs")
            if not res.success:
                return self._fallback(soc, cap, power, net_f[0], w[0])
            consigna = float(res.x[0] - res.x[H])
        except Exception:
            return 0.0

        # No descarregar més que el consum net previst (evita abocar a 0 €)
        max_desc = max(0.0, min(power, net_f[0] - self.margin_kw))
        if consigna < 0.0:
            consigna = max(consigna, -max_desc)

        eps = 1e-4
        max_carrega = max(0.0, min(power, (cap - soc) / self.eta - eps))
        max_descarrega = max(0.0, min(power, soc * self.eta - eps))
        consigna = float(np.clip(consigna, -max_descarrega, max_carrega))

        if abs(consigna) < 1e-6:
            consigna = 0.0
        return consigna

    def _fallback(self, soc, cap, power, net, w_now):
        """Heurística simple si l'LP falla."""
        if net < 0.0:
            return max(0.0, min(power, -net, (cap - soc) / self.eta))
        if w_now > 0.0:
            return -max(0.0, min(power, net * 0.8, soc * self.eta))
        return 0.0

